# logcat regex, which will match the log message generated by `adb logcat -v threadtime`
LOGCAT_THREADTIME_RE = re.compile('^(?P<date>\S+)\s+(?P<time>\S+)\s+(?P<pid>[0-9]+)\s+(?P<tid>[0-9]+)\s+'
                                  '(?P<level>[VDIWEFS])\s+(?P<tag>[^:]*):\s+(?P<content>.*)$')


def lazy_property(func):
    attribute = '_lazy_' + func.__name__

    @property
    @functools.wraps(func)
    def wrapper(self):
        if not hasattr(self, attribute):
            setattr(self, attribute, func(self))
        return getattr(self, attribute)

    return wrapper


def parse_log(log_msg):
    """
    parse a logcat message
    the log should be in threadtime format
    @param log_msg:
    @return:
    """
    m = LOGCAT_THREADTIME_RE.match(log_msg)
    if not m:
        return None
    log_dict = {}
    date = m.group('date')
    time = m.group('time')
    log_dict['pid'] = m.group('pid')
    log_dict['tid'] = m.group('tid')
    log_dict['level'] = m.group('level')
    log_dict['tag'] = m.group('tag')
    log_dict['content'] = m.group('content')
    datetime_str = "%s-%s %s" % (datetime.today().year, date, time)
    log_dict['datetime'] = datetime.strptime(datetime_str, "%Y-%m-%d %H:%M:%S.%f")

    return log_dict


def get_available_devices():
    """
    Get a list of device serials connected via adb
    :return: list of str, each str is a device serial number
    """
    import subprocess
    r = subprocess.check_output(["adb", "devices"])
    if not isinstance(r, str):
        r = r.decode()
    devices = []
    for line in r.splitlines():
        segs = line.strip().split()
        if len(segs) == 2 and segs[1] == "device":
            devices.append(segs[0])
    return devices


def weighted_choice(choices):
    import random
    total = sum(choices[c] for c in list(choices.keys()))
    r = random.uniform(0, total)
    upto = 0
    for c in list(choices.keys()):
        if upto + choices[c] > r:
            return c
        upto += choices[c]


def safe_re_match(regex, content):
    if not regex or not content:
        return None
    else:
        return regex.match(content)


def md5(input_str):
    import hashlib
    return hashlib.md5(input_str.encode('utf-8')).hexdigest()

def generate_report(img_path, html_path, bug_information=None):
    '''Generate report for the test based on the executed events'''
    line_list = []
    
    bug_link_list = []
    # user can click to jump to the corresponding event, contains the event index of each bug
    bug_set = set()
    json_dir = os.path.join(html_path, "report_screenshot.json")
    with open(json_dir, 'r') as json_file:
        report_screens = json.load(json_file)
    
    f_html = open(
        os.path.join(html_path,  "bug_report.html"), 'w', encoding='utf-8'
    )
    f_style = pkg_resources.resource_filename(
                "droidbot", "resources/style/style.html"
            )
    f_style = open(f_style, 'r', encoding='utf-8')
    # f_style = open("droidbot/resources/style/style.html", 'r', encoding='utf-8')
    new_str = "<ul id=\"menu\">" + '\n'
    new_bug_str = ""
    # Pre-load optional llm outputs mapping: event_index -> list[outputs]
    llm_outputs_map = {}
    try:
        llm_path = os.path.join(html_path, 'llm_outputs.json')
        if os.path.exists(llm_path):
            with open(llm_path, 'r', encoding='utf-8') as f_llm:
                llm_items = json.load(f_llm)
                for item in llm_items:
                    llm_outputs_map[item.get('event_index')] = item.get('outputs', [])
    except Exception:
        pass

    for report_screen in report_screens:
        action_count = report_screen['event_index']
        event_name = report_screen.get('event', '')
        phase = report_screen.get('phase', '')
        feature_name = report_screen.get('feature', '')
        img_name = report_screen['screen_shoot']
        img_file = os.path.join(img_path, img_name)

        with open(img_file, "rb") as image_file:
            encoded_string = base64.b64encode(image_file.read()).decode('utf-8')
        header_parts = [action_count]
        if event_name:
            header_parts.append(event_name)
        if phase:
            header_parts.append(f"[{phase}]")
        header_caption = " ".join(header_parts)

        feature_html = ""
        if feature_name:
            feature_html = f"<p class=\"feature-text\">feature: {feature_name}</p>"

        # 3) LLM outputs (if any) below feature line
        llm_html = ""
        outputs = llm_outputs_map.get(action_count)
        if outputs:
            # collapse large raw outputs inside <details>
            snippet_parts = []
            for out in outputs:
                stage = out.get('stage', '')
                raw = out.get('raw', '')
                parsed = out.get('parsed')
                raw_safe = html.escape(raw) if isinstance(raw, str) else html.escape(str(raw))
                parsed_safe = html.escape(parsed) if isinstance(parsed, str) else (html.escape(str(parsed)) if parsed is not None else None)
                snippet_parts.append(
                    "<div class=\"llm-block\">"
                    f"<div class=\"llm-stage\">[LLM:{stage}]</div>"
                    + (f"<pre class=\"llm-raw\">{raw_safe}</pre>" if raw else "")
                    + (f"<pre class=\"llm-parsed\">{parsed_safe}</pre>" if parsed_safe else "")
                    + "</div>"
                )
            llm_html = "<div class=\"llm-section\">" + "".join(snippet_parts) + "</div>"

        line = (
            "      <li>"
            + f"<img src=\"data:image/png;base64,{encoded_string}\" class=\"img\">"
            + f"<p class=\"caption\">{header_caption}</p>"
            + feature_html
            + llm_html
            + "</li>\n"
        )
        
        line_list.append(line)
    for item in line_list:
        new_str = new_str + item
    for item in bug_link_list:
        new_bug_str = new_bug_str + item
    new_str = new_str + "   </ul>"
    old_str = "<ul id=\"menu\"></ul>"
    old_bug_str = "<tr><td>bug_link</td><td>bug_link</td><td>bug_link</td><td>bug_link</td></tr>"
    for line in f_style:
        if bug_information is not None and old_bug_str in line:
            f_html.write(line.replace(old_bug_str, new_bug_str))
            continue
        f_html.write(line.replace(old_str, new_str))
    
def _load_template_parts():
    """Internal helper: split style.html into head(before <ul id="menu"></ul>) and tail(after)."""
    f_style_path = pkg_resources.resource_filename("droidbot", "resources/style/style.html")
    with open(f_style_path, 'r', encoding='utf-8') as f:
        tpl = f.read()
    token = '<ul id="menu"></ul>'
    idx = tpl.find(token)
    if idx == -1:
        # fallback: try to find opening tag, treat remainder as tail
        token_open = '<ul id="menu">'
        idx = tpl.find(token_open)
        if idx == -1:
            return tpl, ''
        head = tpl[:idx] + token_open
        tail = tpl[idx + len(token_open):]
        return head, tail
    head = tpl[:idx]
    tail = tpl[idx + len(token):]
    return head, tail

def start_incremental_report(html_path: str):
    """Create/initialize bug_report.html for incremental appending.
    Writes template head and the opening <ul>, saves the template tail for finalization.
    Safe to call multiple times; only initializes if not already present.
    """
    try:
        report_path = os.path.join(html_path, "bug_report.html")
        tail_path = os.path.join(html_path, "_report_tail.html")
        if os.path.exists(report_path) and os.path.getsize(report_path) > 0:
            return
        head, tail = _load_template_parts()
        with open(report_path, 'w', encoding='utf-8') as f:
            f.write(head)
            f.write('\n  <ul id="menu">\n')
        with open(tail_path, 'w', encoding='utf-8') as f:
            f.write('\n  </ul>')
            f.write(tail)
    except Exception:
        # non-fatal
        pass

def _build_li_for_report(report_screen: dict, img_path: str, html_path: str) -> str:
    """Build a single <li> block for a report_screen entry using relative image path and LLM outputs."""
    action_count = report_screen.get('event_index', '')
    event_name = report_screen.get('event', '')
    phase = report_screen.get('phase', '')
    feature_name = report_screen.get('feature', '')
    img_name = report_screen.get('screen_shoot', '')
    img_file = os.path.join(img_path, img_name)
    # Compute relative src to avoid base64 cost
    try:
        img_rel = os.path.relpath(img_file, html_path).replace('\\','/')
    except Exception:
        img_rel = img_name

    # Header caption
    header_parts = [action_count] if action_count else []
    if event_name:
        header_parts.append(event_name)
    if phase:
        header_parts.append(f"[{phase}]")
    header_caption = " ".join(header_parts)

    feature_html = f"<p class=\"feature-text\">feature: {feature_name}</p>" if feature_name else ""

    # LLM outputs for this action (if any)
    llm_html = ""
    try:
        llm_path = os.path.join(html_path, 'llm_outputs.json')
        outputs = None
        if os.path.exists(llm_path):
            with open(llm_path, 'r', encoding='utf-8') as f_llm:
                items = json.load(f_llm)
                for it in items:
                    if it.get('event_index') == action_count:
                        outputs = it.get('outputs', [])
                        break
        if outputs:
            snippet_parts = []
            for out in outputs:
                stage = out.get('stage', '')
                raw = out.get('raw', '')
                parsed = out.get('parsed')
                raw_safe = html.escape(raw) if isinstance(raw, str) else html.escape(str(raw))
                parsed_safe = html.escape(parsed) if isinstance(parsed, str) else (html.escape(str(parsed)) if parsed is not None else None)
                snippet_parts.append(
                    "<div class=\"llm-block\">"
                    f"<div class=\"llm-stage\">[LLM:{stage}]</div>"
                    + (f"<pre class=\"llm-raw\">{raw_safe}</pre>" if raw else "")
                    + (f"<pre class=\"llm-parsed\">{parsed_safe}</pre>" if parsed_safe else "")
                    + "</div>"
                )
            llm_html = "<div class=\"llm-section\">" + "".join(snippet_parts) + "</div>"
    except Exception:
        pass

    line = (
        "      <li>"
        + f"<img src=\"{img_rel}\" class=\"img\">"
        + f"<p class=\"caption\">{header_caption}</p>"
        + feature_html
        + llm_html
        + "</li>\n"
    )
    return line

def append_incremental_report_item(img_path: str, html_path: str, report_screen: dict):
    """Append a single <li> for the latest action to bug_report.html."""
    try:
        report_path = os.path.join(html_path, "bug_report.html")
        if not os.path.exists(report_path):
            start_incremental_report(html_path)
        line = _build_li_for_report(report_screen, img_path, html_path)
        with open(report_path, 'a', encoding='utf-8') as f:
            f.write(line)
    except Exception:
        pass

def finalize_incremental_report(html_path: str):
    """Close the <ul> and write the remaining tail of the template."""
    try:
        report_path = os.path.join(html_path, "bug_report.html")
        tail_path = os.path.join(html_path, "_report_tail.html")
        if not os.path.exists(report_path):
            return
        if os.path.exists(tail_path):
            with open(tail_path, 'r', encoding='utf-8') as f:
                tail = f.read()
            with open(report_path, 'a', encoding='utf-8') as rf:
                rf.write(tail)
            try:
                os.remove(tail_path)
            except Exception:
                pass
    except Exception:
        pass

