from colorama import Fore, Style     
def print_with_color(text: str, color=""):
    if color == "red":
        print(Fore.RED + text)
    elif color == "green":
        print(Fore.GREEN + text)
    elif color == "yellow":
        print(Fore.YELLOW + text)
    elif color == "blue":
        print(Fore.BLUE + text)
    elif color == "magenta":
        print(Fore.MAGENTA + text)
    elif color == "cyan":
        print(Fore.CYAN + text)
    elif color == "white":
        print(Fore.WHITE + text)
    elif color == "black":
        print(Fore.BLACK + text)
    else:
        print(text)
    print(Style.RESET_ALL)

def get_view_str(view):
    if view is None:
        return "None"
    result = ""
    if view["text"] is not None:
        result += f'text="{view["text"]}"'
        return result
    if view["content_description"] is not None:
        result += f'desc="{view["content_description"]}"'
        return result
    if view["resource_id"] is not None:
        result += f'id="{view["resource_id"]}"'
        return result
    return result
import cv2
import numpy as np
def merge_two_images(img1, img2, merged_img, gap=50):
    img1 = cv2.imread(img1)
    img2 = cv2.imread(img2)

    gap = 40
    height = max(img1.shape[0], img2.shape[0])
    width = img1.shape[1] + img2.shape[1] + gap

    merged = np.ones((height + 100, width, 3), dtype=np.uint8) * 255

    merged[100:100+img1.shape[0], :img1.shape[1]] = img1
    merged[100:100+img2.shape[0], img1.shape[1]+gap:img1.shape[1]+gap+img2.shape[1]] = img2

    cv2.putText(merged, "last_page", (50, 70), cv2.FONT_HERSHEY_SIMPLEX, 2, (0,0,0), 3)
    cv2.putText(merged, "current_page", (img1.shape[1]+gap+50, 70), cv2.FONT_HERSHEY_SIMPLEX, 2, (0,0,0), 3)

    cv2.imwrite(merged_img, merged)


def format_execution_trace_for_llm(
    executed_summary,
    initial_page_description=None,
    use_brief=False,
    initial_page_brief_description=None,
):
    """
    Convert step logs into a linear screen/action trace so the same screen
    description is not repeated as both the previous and next page.
    """
    initial_screen_description = initial_page_description
    if use_brief and initial_page_brief_description:
        initial_screen_description = initial_page_brief_description

    if not executed_summary:
        return initial_screen_description or initial_page_description or "N/A"

    lines = []
    first_step = next((item for item in executed_summary if isinstance(item, dict)), None)
    initial_screen = initial_screen_description or (
        first_step.get("prev_page_description", "") if first_step else ""
    )

    if initial_screen:
        lines.append(f"S0: {initial_screen}")

    screen_index = 0
    action_index = 1
    for item in executed_summary:
        if not isinstance(item, dict):
            continue

        action_description = item.get("action_description", "")
        result = item.get("result", "")
        state_change_summary = item.get("state_change_summary", "")
        next_page_description = item.get("next_page_description", "") or item.get("current_page_description", "")
        if use_brief:
            next_page_description = item.get("next_page_brief_description", "") or next_page_description

        action_line = f"A{action_index}"
        if result:
            action_line += f" [{result}]"
        if action_description:
            action_line += f": {action_description}"
        if state_change_summary:
            action_line += f" | change: {state_change_summary}"
        lines.append(action_line)

        screen_index += 1
        if next_page_description:
            lines.append(f"S{screen_index}: {next_page_description}")

        action_index += 1

    return "\n".join(lines) if lines else (initial_screen_description or initial_page_description or "N/A")

# --- Console log tee helpers ---
_TEE_STDOUT_ORIG = None
_TEE_STDERR_ORIG = None
_TEE_LOG_FILE = None

class _TeeStream:
    """A thin tee that preserves TTY semantics of the primary stream.
    Many color libraries check isatty()/fileno()/encoding to decide coloring.
    """
    def __init__(self, primary, *others):
        self._primary = primary
        self._streams = [primary, *others]

    def write(self, data):
        for s in self._streams:
            try:
                s.write(data)
                s.flush()
            except Exception:
                pass

    def writelines(self, lines):
        for line in lines:
            self.write(line)

    def flush(self):
        for s in self._streams:
            try:
                s.flush()
            except Exception:
                pass

    def isatty(self):
        try:
            return self._primary.isatty()
        except Exception:
            return False

    def fileno(self):
        try:
            return self._primary.fileno()
        except Exception:
            raise

    @property
    def encoding(self):
        return getattr(self._primary, 'encoding', 'utf-8')

    @property
    def errors(self):
        return getattr(self._primary, 'errors', None)

    @property
    def closed(self):
        return getattr(self._primary, 'closed', False)

    @property
    def name(self):
        return getattr(self._primary, 'name', '<tee>')

    def readable(self):
        return False

    def writable(self):
        return True

    def seekable(self):
        return False

def start_console_log_tee(log_path: str):
    """Duplicate all console output (stdout/stderr) into a log file.
    Safe to call once per process; subsequent calls overwrite previous tee.
    """
    global _TEE_STDOUT_ORIG, _TEE_STDERR_ORIG, _TEE_LOG_FILE
    try:
        os.makedirs(os.path.dirname(log_path), exist_ok=True)
    except Exception:
        pass
    # Close any existing file handle first
    if _TEE_LOG_FILE:
        try:
            _TEE_LOG_FILE.close()
        except Exception:
            pass
        _TEE_LOG_FILE = None

    _TEE_LOG_FILE = open(log_path, 'a', encoding='utf-8')
    _TEE_STDOUT_ORIG = sys.stdout
    _TEE_STDERR_ORIG = sys.stderr
    sys.stdout = _TeeStream(sys.stdout, _TEE_LOG_FILE)
    sys.stderr = _TeeStream(sys.stderr, _TEE_LOG_FILE)

def stop_console_log_tee():
    """Restore stdout/stderr and close the log file."""
    global _TEE_STDOUT_ORIG, _TEE_STDERR_ORIG, _TEE_LOG_FILE
    if _TEE_STDOUT_ORIG is not None:
        sys.stdout = _TEE_STDOUT_ORIG
        _TEE_STDOUT_ORIG = None
    if _TEE_STDERR_ORIG is not None:
        sys.stderr = _TEE_STDERR_ORIG
        _TEE_STDERR_ORIG = None
    if _TEE_LOG_FILE is not None:
        try:
            _TEE_LOG_FILE.flush()
            _TEE_LOG_FILE.close()
        except Exception:
            pass
        _TEE_LOG_FILE = None

def find_aapt2():
    try:
        subprocess.run(["aapt2", "version"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return "aapt2"
    except FileNotFoundError:
        pass

    android_home = os.environ.get("ANDROID_HOME") or os.environ.get("ANDROID_SDK_ROOT")
    if not android_home:
        print("❌ 错误: 未找到 ANDROID_HOME 环境变量。请确保已安装 Android SDK。")
        return None

    build_tools_dir = Path(android_home) / "build-tools"
    if not build_tools_dir.exists():
        print(f"❌ 错误: 未找到 build-tools 目录: {build_tools_dir}")
        return None

    versions = sorted([d for d in build_tools_dir.iterdir() if d.is_dir()], reverse=True)
    
    if not versions:
        print("❌ 错误: build-tools 目录下为空。")
        return None

    exe_name = "aapt2.exe" if platform.system() == "Windows" else "aapt2"

    for version_dir in versions:
        aapt2_path = version_dir / exe_name
        if aapt2_path.exists():
            print(f"✅ 发现 aapt2: {aapt2_path}")
            return str(aapt2_path)

    print("❌ 错误: 在 build-tools 中未找到 aapt2。")
    return None

def extract_strings(apk_path, output_path):
    aapt2_cmd = find_aapt2()
    if not aapt2_cmd:
        return

    if not os.path.exists(apk_path):
        print(f"❌ 错误: 找不到 APK 文件: {apk_path}")
        return

    print(f"🚀 开始提取文本...")
    print(f"📂 输入: {apk_path}")
    print(f"📄 输出: {output_path}")

    cmd = [aapt2_cmd, "dump", "strings", apk_path]

    try:
        with open(output_path, "w", encoding="utf-8") as f:
            result = subprocess.run(cmd, stdout=f, stderr=subprocess.PIPE, text=True)
            
            if result.returncode == 0:
                print(f"✨ 成功! 文本已保存到本地: {output_path}")
                print("   (这个文件就是 Fastbot 所需的 max.valid.strings 格式)")
            else:
                print(f"❌ 失败: aapt2 执行出错:\n{result.stderr}")
    except Exception as e:
        print(f"❌ 发生异常: {str(e)}")

def append_llm_output(stage: str, raw_response: str, parsed: str = None, output_dir: str = None,action_count: int = None):
        """Persist LLM outputs per action (event index) for later report rendering.
        Appends under output_dir/llm_outputs.json as an array of items per event_index.
        Note: We intentionally DO NOT store prompt content for privacy/safety.
        Each item schema:
        {
            "event_index": "<int as string>",
            "outputs": [
                {"stage": str, "raw": str, "parsed": Optional[str]}
            ]
        }
        """
        try:
            out_path = os.path.join(output_dir, "llm_outputs.json")
            try:
                with open(out_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
            except Exception:
                data = []

            ev_idx = str(action_count)
            entry = None
            for item in data:
                if item.get("event_index") == ev_idx:
                    entry = item
                    break
            if entry is None:
                entry = {"event_index": ev_idx, "outputs": []}
                data.append(entry)
            # Do not persist prompts; only store stage/raw/parsed
            entry["outputs"].append({
                "stage": stage,
                "raw": raw_response if isinstance(raw_response, str) else str(raw_response),
                "parsed": parsed if isinstance(parsed, str) or parsed is None else str(parsed)
            })
            with open(out_path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
        except Exception as e:
            print(f"Warning: Failed to write llm outputs: {e}")
